fun interface Command { fun execute() }
class InsertText(private val doc: Document, private val text: String) : Command {
    override fun execute() = doc.insert(text)
}

val history = ArrayDeque<Command>()
fun run(c: Command) { c.execute(); history.addLast(c) }

sealed interface Edit { data class Insert(val pos: Int, val text: String) : Edit }
fun apply(e: Edit) = when (e) {          // exhaustive, no else
    is Edit.Insert -> doc.insert(e.pos, e.text)
}
